#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";

const arg = (name, fallback = null) =>
  process.argv
    .find((a) => a.startsWith(`--${name}=`))
    ?.slice(name.length + 3) ?? fallback;
const requirementsDir = arg("requirements");
const featuresDir = arg("features");
const idPattern = new RegExp(arg("id-pattern", "@R-\\d{4}"), "g");
const reqIdPattern = new RegExp(arg("req-id-pattern", "R-\\d{4}"));
const json = process.argv.includes("--json");

if (!requirementsDir || !featuresDir) {
  console.error(
    "Usage: node coverage-map.mjs --requirements=<dir> --features=<dir> [--json]",
  );
  process.exit(2);
}

const walk = (dir, out = []) => {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
};

const rel = (file) => path.relative(process.cwd(), file).replace(/\\/g, "/");
const requirements = new Map();
for (const file of walk(requirementsDir).filter((f) =>
  /\.(md|txt)$/i.test(f),
)) {
  const id = rel(file).match(reqIdPattern)?.[0];
  if (!id) continue;
  const text = fs.readFileSync(file, "utf8");
  const candidates = text
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => /^([-*]|\d+[.)])\s+\S/.test(line))
    .map((line) => line.replace(/^([-*]|\d+[.)])\s+/, "").trim())
    .filter((line) => line.length > 8);
  const existing = requirements.get(id) ?? { id, files: [], candidates: [] };
  existing.files.push(rel(file));
  existing.candidates.push(...candidates);
  requirements.set(id, existing);
}

const scenariosById = new Map();
const orphaned = [];
for (const file of walk(featuresDir).filter((f) => f.endsWith(".feature"))) {
  const text = fs.readFileSync(file, "utf8");
  const scenarioTitles = [
    ...text.matchAll(/^\s*Scenario(?: Outline)?:\s*(.+)$/gm),
  ].map((m) => m[1].trim());
  const tags = text.match(idPattern) ?? [];
  if (!tags.length) {
    for (const title of scenarioTitles)
      orphaned.push({
        scenario: title,
        file: rel(file),
        reason: "no requirement tag",
      });
    continue;
  }
  for (const tag of tags) {
    const id = tag.replace(/^@/, "");
    const list = scenariosById.get(id) ?? [];
    for (const title of scenarioTitles)
      list.push({ title, file: rel(file), tag });
    scenariosById.set(id, list);
  }
}

const covered = [];
const missing = [];
for (const [id, req] of requirements) {
  const scenarios = scenariosById.get(id) ?? [];
  if (scenarios.length) covered.push({ id, scenarios });
  else
    missing.push({
      id,
      files: req.files,
      suggestedScenarios: [...new Set(req.candidates)].slice(0, 8),
    });
}
for (const [id, scenarios] of scenariosById) {
  if (!requirements.has(id))
    for (const scenario of scenarios)
      orphaned.push({
        ...scenario,
        reason: `tagged ${id} but no requirement exists`,
      });
}

const report = { covered, missing, orphaned };
if (json) console.log(JSON.stringify(report, null, 2));
else {
  console.log(`Covered: ${covered.length}`);
  console.log(`Missing: ${missing.length}`);
  console.log(`Orphaned: ${orphaned.length}`);
}
process.exit(missing.length ? 1 : 0);

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";

const args = process.argv.slice(2);
const root = path.resolve(
  args.find((a) => a.startsWith("--root="))?.slice(7) ?? process.cwd(),
);
const json = args.includes("--json") || true;
const skip = new Set([
  ".git",
  "node_modules",
  "dist",
  "build",
  "coverage",
  ".next",
]);

const readJson = (file) => {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return null;
  }
};

const walk = (dir, out = []) => {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (!skip.has(entry.name)) walk(path.join(dir, entry.name), out);
    } else out.push(path.join(dir, entry.name));
  }
  return out;
};

const rel = (file) => path.relative(root, file).replace(/\\/g, "/");
const files = walk(root);
const packageFiles = files.filter(
  (file) => path.basename(file) === "package.json",
);
const packages = packageFiles
  .map((file) => ({ file, dir: path.dirname(file), json: readJson(file) }))
  .filter((item) => item.json);
const dependenciesOf = (pkg) => ({
  ...(pkg.dependencies ?? {}),
  ...(pkg.devDependencies ?? {}),
  ...(pkg.peerDependencies ?? {}),
});
const allScripts = packages.flatMap((pkg) =>
  Object.entries(pkg.json.scripts ?? {}).map(([name, command]) => ({
    package: rel(pkg.file),
    name,
    command,
  })),
);

const hasDependency = (name) =>
  packages.find((pkg) => dependenciesOf(pkg.json)[name]);
const config = (names) =>
  files.find((file) => names.includes(path.basename(file)));
const testDirs = [
  ...new Set(
    files
      .filter((file) =>
        /(^|[\\/])(e2e|tests?|specs?|cypress)([\\/]|$)/i.test(file),
      )
      .map((file) => rel(path.dirname(file)).split("/").slice(0, 3).join("/")),
  ),
].filter(Boolean);

let framework = "none";
let workspace = null;
let version = null;
if (hasDependency("playwright-bdd")) {
  const hit = hasDependency("playwright-bdd");
  framework = "playwright-bdd";
  workspace = rel(hit.dir);
  version = dependenciesOf(hit.json)["playwright-bdd"];
} else if (
  hasDependency("@playwright/test") ||
  config([
    "playwright.config.ts",
    "playwright.config.js",
    "playwright.config.mjs",
  ])
) {
  const hit = hasDependency("@playwright/test");
  framework = "playwright";
  workspace = hit ? rel(hit.dir) : ".";
  version = hit ? dependenciesOf(hit.json)["@playwright/test"] : null;
} else if (
  hasDependency("cypress") ||
  config(["cypress.config.ts", "cypress.config.js", "cypress.config.mjs"])
) {
  const hit = hasDependency("cypress");
  framework = hasDependency("@badeball/cypress-cucumber-preprocessor")
    ? "cypress-cucumber"
    : "cypress";
  workspace = hit ? rel(hit.dir) : ".";
  version = hit ? dependenciesOf(hit.json).cypress : null;
} else if (
  hasDependency("@wdio/cli") ||
  config(["wdio.conf.ts", "wdio.conf.js"])
) {
  const hit = hasDependency("@wdio/cli");
  framework = "webdriverio";
  workspace = hit ? rel(hit.dir) : ".";
  version = hit ? dependenciesOf(hit.json)["@wdio/cli"] : null;
}

const e2eScripts = allScripts.filter((script) =>
  /e2e|playwright|cypress|wdio|selenium|browser|acceptance/i.test(
    `${script.name} ${script.command}`,
  ),
);
const devServer = allScripts.find((script) =>
  /^(dev|start|serve)$|dev:|start:/i.test(script.name),
);
const report = {
  rootDir: root,
  framework,
  version,
  workspace,
  configPath: config([
    "playwright.config.ts",
    "playwright.config.js",
    "playwright.config.mjs",
    "cypress.config.ts",
    "cypress.config.js",
    "wdio.conf.ts",
    "wdio.conf.js",
  ])
    ? rel(
        config([
          "playwright.config.ts",
          "playwright.config.js",
          "playwright.config.mjs",
          "cypress.config.ts",
          "cypress.config.js",
          "wdio.conf.ts",
          "wdio.conf.js",
        ]),
      )
    : null,
  testsDir: testDirs[0] ?? null,
  discoveredTestDirs: testDirs,
  featureFiles: files.filter((file) => file.endsWith(".feature")).map(rel),
  specFiles: files
    .filter((file) => /\.(spec|test|cy|e2e)\.[cm]?[jt]sx?$/.test(file))
    .map(rel),
  e2eScripts,
  devServer: devServer ?? null,
  resultHints: [
    "test-results",
    "playwright-report",
    "cypress/results",
    "reports",
  ].filter((hint) => fs.existsSync(path.join(root, hint))),
  nextAction:
    framework === "none"
      ? "Ask user which E2E framework to use before authoring tests."
      : "Use detected framework conventions before writing tests.",
};

if (json) console.log(JSON.stringify(report, null, 2));

#!/usr/bin/env node
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";

const require = createRequire(import.meta.url);
const arg = (name, fallback = null) =>
  process.argv
    .find((a) => a.startsWith(`--${name}=`))
    ?.slice(name.length + 3) ?? fallback;
const baseUrl = arg("url", "http://localhost:3000");
const route = arg("route", "/");
const out = arg("out");
const timeout = Number(arg("timeout", "30000"));

let playwright;
try {
  playwright = require("@playwright/test");
} catch {
  try {
    playwright = require("playwright");
  } catch {
    console.error(
      "Playwright is not installed in this workspace. Install @playwright/test or use MCP browser tools.",
    );
    process.exit(2);
  }
}

const clean = `(value) => (value || "").trim().replace(/\\s+/g, " ").slice(0, 180)`;
const target = new URL(route, baseUrl).toString();
const browser = await playwright.chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto(target, { waitUntil: "load", timeout });
try {
  await page.waitForLoadState("networkidle", { timeout });
} catch {}
const report = await page.evaluate((cleanSource) => {
  const clean = eval(cleanSource);
  const uniq = (items) => [...new Set(items.filter(Boolean))];
  const textOf = (selector) =>
    uniq(
      [...document.querySelectorAll(selector)].map((node) =>
        clean(node.textContent || node.getAttribute("aria-label")),
      ),
    );
  const dataAttributes = {};
  for (const node of document.querySelectorAll("*"))
    for (const attr of node.attributes)
      if (/^data-/.test(attr.name))
        (dataAttributes[attr.name] ||= new Set()).add(attr.value);
  return {
    url: location.href,
    title: document.title,
    headings: textOf("h1,h2,h3,h4,h5,h6"),
    buttons: textOf("button,[role=button]"),
    links: textOf("a[href]"),
    labels: textOf("label,[aria-label]"),
    dataAttributes: Object.fromEntries(
      Object.entries(dataAttributes).map(([key, values]) => [
        key,
        [...values].slice(0, 100),
      ]),
    ),
    bodyPreview: clean(document.body.innerText).slice(0, 1500),
  };
}, clean);
await browser.close();
const rendered = JSON.stringify(report, null, 2) + "\n";
if (out) {
  fs.mkdirSync(path.dirname(path.resolve(out)), { recursive: true });
  fs.writeFileSync(out, rendered, "utf8");
} else process.stdout.write(rendered);

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";

const testsDir = process.argv
  .find((a) => a.startsWith("--tests-dir="))
  ?.slice(12);
const json = process.argv.includes("--json");
if (!testsDir) {
  console.error("Usage: node health-check.mjs --tests-dir=<dir> [--json]");
  process.exit(2);
}

const walk = (dir, out = []) => {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (
      entry.isDirectory() &&
      !entry.name.startsWith(".") &&
      entry.name !== "node_modules"
    )
      walk(full, out);
    else if (entry.isFile()) out.push(full);
  }
  return out;
};
const rel = (file) => path.relative(process.cwd(), file).replace(/\\/g, "/");
const findings = [];
const push = (rule, file, line, message) =>
  findings.push({ rule, file: rel(file), line, message });

for (const file of walk(testsDir).filter((f) =>
  /\.(feature|spec|test|cy|e2e|steps?)\.[cm]?[jt]sx?$|\.feature$/i.test(f),
)) {
  const lines = fs.readFileSync(file, "utf8").split(/\r?\n/);
  let hasWhen = false;
  let hasThen = false;
  lines.forEach((line, index) => {
    if (
      /(waitForTimeout|cy\.wait\s*\(\s*\d+|Thread\.sleep)/.test(line) &&
      !/@allow-timeout/.test(line)
    )
      push(
        "no-fixed-waits",
        file,
        index + 1,
        "Use web-first synchronization instead of fixed time waits.",
      );
    if (
      /(locator|getBy|find|get)\s*\(\s*["'`][^"'`]*\.[A-Za-z][A-Za-z0-9_-]+/.test(
        line,
      )
    )
      push(
        "no-css-class-selectors",
        file,
        index + 1,
        "Use role, label, text, or stable data attributes instead of CSS classes.",
      );
    if (/^\s*(Given|When|Then|And|But)\b.*\[data-/.test(line))
      push(
        "no-dom-language-gherkin",
        file,
        index + 1,
        "Gherkin must describe user behavior, not DOM selectors.",
      );
    if (/^\s*When\b/.test(line)) hasWhen = true;
    if (/^\s*Then\b/.test(line)) hasThen = true;
  });
  if (file.endsWith(".feature")) {
    if (!/@R-\d{4}/.test(lines.join("\n")))
      push(
        "missing-requirement-tag",
        file,
        1,
        "Feature file needs an @R-XXXX requirement tag.",
      );
    if (!hasWhen)
      push("missing-when", file, 1, "Feature file has no user action step.");
    if (!hasThen)
      push(
        "missing-then",
        file,
        1,
        "Feature file has no observable outcome step.",
      );
  }
}

if (json)
  console.log(JSON.stringify({ total: findings.length, findings }, null, 2));
else if (findings.length)
  findings.forEach((f) =>
    console.log(`[${f.rule}] ${f.file}:${f.line} ${f.message}`),
  );
else console.log("E2E health check: clean");
process.exit(findings.length ? 1 : 0);

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";

const json = process.argv.includes("--json");
const root = process.cwd();
const skip = new Set(["node_modules", ".git", "dist", "build", "coverage"]);

const walk = (dir, predicate, out = []) => {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (!skip.has(entry.name))
        walk(path.join(dir, entry.name), predicate, out);
    } else {
      const full = path.join(dir, entry.name);
      if (predicate(full))
        out.push(path.relative(root, full).replace(/\\/g, "/"));
    }
  }
  return out;
};

const packageJson = path.join(root, "package.json");
const scripts = fs.existsSync(packageJson)
  ? (JSON.parse(fs.readFileSync(packageJson, "utf8")).scripts ?? {})
  : {};

const configs = walk(root, (file) =>
  /(^|[\/])(playwright|cypress)\.config\.[cm]?[jt]s$/.test(file),
);
const tests = walk(root, (file) =>
  /(e2e|tests?|specs?).*\.(spec|test)\.[cm]?[jt]sx?$/.test(
    file.replace(/\\/g, "/"),
  ),
);
const appEntrypoints = walk(root, (file) =>
  /(src|app|pages|routes)[\/].*\.[jt]sx?$/.test(file),
);
const e2eScripts = Object.entries(scripts).filter(([name, command]) =>
  /e2e|playwright|cypress/i.test(`${name} ${command}`),
);

const report = {
  configs,
  tests,
  e2eScripts: e2eScripts.map(([name, command]) => ({ name, command })),
  appEntrypoints: appEntrypoints.slice(0, 50),
  recommendations: [
    configs.length
      ? "Use existing runner config."
      : "Add a runner config before writing e2e tests.",
    e2eScripts.length
      ? "Use an existing e2e npm script."
      : "Add an npm script for the selected e2e runner.",
    "Prefer role, label, and text locators over CSS selectors.",
  ],
};

if (json) console.log(JSON.stringify(report, null, 2));
else {
  console.log("# E2E Surface\n");
  console.log(`Configs: ${configs.length ? configs.join(", ") : "none"}`);
  console.log(`Tests: ${tests.length}`);
  console.log("\n## E2E Scripts");
  for (const item of report.e2eScripts)
    console.log(`- ${item.name}: ${item.command}`);
  console.log("\n## Recommendations");
  for (const item of report.recommendations) console.log(`- ${item}`);
}

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";

const features = process.argv
  .find((a) => a.startsWith("--features="))
  ?.slice(11);
const specs = process.argv.find((a) => a.startsWith("--specs="))?.slice(8);
const json = process.argv.includes("--json");
if (!features && !specs) {
  console.error(
    "Usage: node meaningfulness-audit.mjs --features=<dir> [--specs=<dir>] [--json]",
  );
  process.exit(2);
}
const walk = (dir, out = []) => {
  if (!dir || !fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (
      entry.isDirectory() &&
      !entry.name.startsWith(".") &&
      entry.name !== "node_modules"
    )
      walk(full, out);
    else if (entry.isFile()) out.push(full);
  }
  return out;
};
const rel = (file) => path.relative(process.cwd(), file).replace(/\\/g, "/");
const findings = [];
const push = (rule, file, line, message) =>
  findings.push({ rule, file: rel(file), line, message });

for (const file of walk(features).filter((f) => f.endsWith(".feature"))) {
  const text = fs.readFileSync(file, "utf8");
  const blocks = text.split(/^\s*Scenario(?: Outline)?:/m).slice(1);
  if (!/@R-\d{4}/.test(text))
    push(
      "no-requirement-tag",
      file,
      1,
      "Scenarios must be traceable to @R-XXXX.",
    );
  blocks.forEach((block, index) => {
    const line = text.slice(0, text.indexOf(block)).split(/\r?\n/).length;
    if (!/^\s*When\b/m.test(block))
      push(
        "no-user-action",
        file,
        line,
        `Scenario ${index + 1} has no When step.`,
      );
    if (!/^\s*Then\b/m.test(block))
      push(
        "no-observable-outcome",
        file,
        line,
        `Scenario ${index + 1} has no Then step.`,
      );
    if (
      /^\s*Then\b.{0,80}\b(is|are)\s+(visible|shown|displayed|present)\.?\s*$/im.test(
        block,
      ) &&
      !/count|contains|enabled|disabled|navigat|saved|created|deleted|updated/i.test(
        block,
      )
    )
      push(
        "presence-only",
        file,
        line,
        "Presence-only assertions are not meaningful enough.",
      );
  });
}
for (const file of walk(specs).filter((f) =>
  /\.(spec|test|cy|e2e)\.[cm]?[jt]sx?$/.test(f),
)) {
  const text = fs.readFileSync(file, "utf8");
  for (const match of text.matchAll(
    /\b(it|test)\s*\(\s*(["'`])([^"'`]+)\2([\s\S]*?)(?=\n\s*\b(?:it|test)\s*\(|\n\s*\}\s*\)\s*;?)/g,
  )) {
    const body = match[4];
    const line = text.slice(0, match.index).split(/\r?\n/).length;
    const expects = body.match(/\b(expect|should)\s*\(/g) ?? [];
    if (!expects.length)
      push(
        "no-expectation",
        file,
        line,
        `Test "${match[3]}" has no assertion.`,
      );
    else if (expects.length === 1 && /(toBeVisible|be\.visible)/.test(body))
      push(
        "visible-only",
        file,
        line,
        `Test "${match[3]}" only checks visibility.`,
      );
  }
}
if (json)
  console.log(JSON.stringify({ total: findings.length, findings }, null, 2));
else if (findings.length)
  findings.forEach((f) =>
    console.log(`[${f.rule}] ${f.file}:${f.line} ${f.message}`),
  );
else console.log("Meaningfulness audit: clean");
process.exit(findings.length ? 1 : 0);

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";

const target = process.argv.find((a) => a.startsWith("--results="))?.slice(10);
const filter = process.argv.find((a) => a.startsWith("--filter="))?.slice(9);
const json = process.argv.includes("--json");
if (!target) {
  console.error(
    "Usage: node test-report-parser.mjs --results=<file-or-dir> [--filter=@R-0001] [--json]",
  );
  process.exit(2);
}

const collect = (item, out = []) => {
  if (!fs.existsSync(item)) return out;
  const stat = fs.statSync(item);
  if (stat.isDirectory())
    for (const entry of fs.readdirSync(item))
      collect(path.join(item, entry), out);
  else if (/\.(xml|json)$/i.test(item)) out.push(item);
  return out;
};
const extractTags = (text) => text?.match(/@[A-Za-z0-9_-]+/g) ?? [];
const cases = [];
for (const file of collect(target)) {
  const text = fs.readFileSync(file, "utf8");
  if (file.endsWith(".json")) {
    try {
      const parsed = JSON.parse(text);
      const suites = parsed.suites ?? [];
      const visit = (suite, parents = []) => {
        for (const child of suite.suites ?? [])
          visit(child, [...parents, suite.title].filter(Boolean));
        for (const spec of suite.specs ?? [])
          for (const test of spec.tests ?? [])
            for (const result of test.results ?? [])
              cases.push({
                source: file,
                suite: parents.join(" > "),
                scenario: spec.title,
                status:
                  result.status === "passed"
                    ? "passed"
                    : result.status === "skipped"
                      ? "skipped"
                      : "failed",
                durationMs: result.duration ?? 0,
                message: result.error?.message ?? null,
                tags: extractTags(spec.title),
              });
      };
      suites.forEach((suite) => visit(suite));
    } catch {}
  } else {
    for (const match of text.matchAll(
      /<testcase\b([^>]*)>([\s\S]*?)<\/testcase>|<testcase\b([^\/]*)\/>/g,
    )) {
      const attrs = match[1] ?? match[3] ?? "";
      const body = match[2] ?? "";
      const attr = (name) =>
        attrs.match(new RegExp(`${name}="([^"]*)"`))?.[1] ?? "";
      const scenario = attr("name");
      const failed = /<(failure|error)\b/.test(body);
      const skipped = /<skipped\b/.test(body);
      cases.push({
        source: file,
        suite: attr("classname"),
        scenario,
        status: failed ? "failed" : skipped ? "skipped" : "passed",
        durationMs: Number(attr("time") || 0) * 1000,
        message: body.match(/message="([^"]*)"/)?.[1] ?? null,
        tags: extractTags(scenario),
      });
    }
  }
}
const filtered = filter
  ? cases.filter(
      (item) => item.scenario.includes(filter) || item.tags.includes(filter),
    )
  : cases;
const report = {
  total: filtered.length,
  passed: filtered.filter((c) => c.status === "passed").length,
  failed: filtered.filter((c) => c.status === "failed").length,
  skipped: filtered.filter((c) => c.status === "skipped").length,
  failures: filtered.filter((c) => c.status === "failed"),
};
if (json) console.log(JSON.stringify(report, null, 2));
else
  console.log(
    `total ${report.total}\npassed ${report.passed}\nfailed ${report.failed}\nskipped ${report.skipped}`,
  );
process.exit(report.failed ? 1 : 0);

